async function loadQsoIdeas(){qsoIdeasButton.disabled=true;try{await pendingDxLookup;const response=await fetch('/programs/ElmerConversation.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Elmer-Action':'qso-ideas'},body:'{}'}),data=await response.json().catch(()=>({}));if(response.status===401){location.href='/login.php';return}if(!response.ok)throw new Error(data.error||'RigPi could not prepare QSO Ideas.');qsoIdeasOriginal=Array.isArray(data.ideas)?data.ideas:[];if(!qsoIdeasOriginal.length)throw new Error('No QSO Ideas are available for this station.');qsoIdeas=await translatedQsoIdeas(qsoIdeasOriginal);qsoIdeasTitle.textContent=`QSO idea for ${String(data.call||'the other station')}`;showQsoIdea(0)}catch(error){statusBox.textContent=error.message}finally{qsoIdeasButton.disabled=false}}
