let elmerServiceConnected=false;
function setElmerServiceState(data){
  elmerServiceConnected=data.status==='connected';
  const checking=data.status==='checking';
  setupRequired.hidden=elmerServiceConnected||checking;
  button.disabled=!elmerServiceConnected;
  question.disabled=!elmerServiceConnected;
  if(elmerServiceConnected||checking)return;
  if(data.status==='pending')setupMessage.textContent=`Elmer pairing is waiting for administrator approval${data.code?' (code '+data.code+')':''}. Approval may take up to 24 hours. You may leave this page and return later.`;
  else if(data.status==='error')setupMessage.textContent=data.error||'RigPi could not check the Elmer service. Open Configure Elmer to reconnect it.';
  else setupMessage.textContent='Ask Elmer must be connected before it can answer questions. Open Configure Elmer to connect this RigPi.';
}
async function checkElmerService(){
  setElmerServiceState({status:'checking'});
  try{
    const response=await fetch('/programs/ElmerService.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Elmer-Action':'service-config'},body:JSON.stringify({action:'status'})});
    if(response.status===401){location.href='/login.php';return false}
    const data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(data.error||'RigPi could not check the Elmer service.');
    setElmerServiceState(data);return elmerServiceConnected
  }catch(error){setElmerServiceState({status:'error',error:error.message});return false}
}
setupCheck.addEventListener('click',checkElmerService);
form.addEventListener('submit',event=>{if(elmerServiceConnected)return;event.preventDefault();event.stopImmediatePropagation();setupRequired.hidden=false;checkElmerService()},true);
